    /*
     * Add to the Products
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Insurer
     */
    public Insurer addToProducts( UUID parentId, InsuranceProduct addTo ) {
	    LOGGER.info("handling AssignProductsToInsurerEvent - " );
	    
	    Insurer parentEntity = repository.findById(parentId).get();
	    InsuranceProduct child = registry.project( InsuranceProduct.class, addTo.getInsuranceProductId());
	    
	    parentEntity.getProducts().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

